@push('head')
<style>
.id-wrap{max-width:1160px;margin:0 auto;padding:48px 24px 80px}.id-nav{display:flex;gap:20px;flex-wrap:wrap;margin-bottom:32px}.id-hero{padding:48px 0;max-width:850px}.id-hero h1{font-size:clamp(30px,5vw,54px);line-height:1.5;margin:12px 0}.id-lead{font-size:19px;line-height:2;color:var(--muted)}.id-actions{display:flex;gap:14px;flex-wrap:wrap;margin:24px 0}.id-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:18px}.id-card{border:1px solid var(--line, #334155);padding:24px;border-radius:18px;background:var(--surface, #0f172a)}.id-card p{line-height:1.9}.id-muted{color:var(--muted)}.id-pill{display:inline-block;padding:4px 10px;border-radius:20px;background:#123647;color:#a9e5ff;font-size:13px}.id-code{background:#07131f;color:#c8eaff;border:1px solid #28425b;border-radius:14px;padding:20px;white-space:pre-wrap;overflow-wrap:anywhere;direction:ltr;text-align:left}.id-wrap h2{margin-top:40px}.id-wrap input,.id-wrap select{max-width:100%;padding:12px;border:1px solid #3c526b;border-radius:8px;background:transparent;color:inherit}.id-note{padding:20px;border-inline-start:3px solid #38bdf8;background:var(--info-bg);margin:24px 0;line-height:2}
</style>
@endpush
